describe('File Upload Retry Functionality', () => {
    beforeEach(() => {
        cy.visit('/upload'); // Replace with the actual URL of the upload page
    });

    it('should successfully retry a failed upload without re-selecting the file', () => {
        const filePath = 'path/to/your/file.txt'; // Replace with the actual file path

        // Simulate a failed upload
        cy.get('input[type="file"]').attachFile(filePath);
        cy.get('button.upload').click();
        cy.intercept('POST', '/upload', { statusCode: 500 }).as('uploadRequest'); // Simulate server error
        cy.wait('@uploadRequest');

        // Retry the upload
        cy.get('button.retry').click();
        cy.intercept('POST', '/upload', { statusCode: 200 }).as('retryUploadRequest'); // Simulate successful retry
        cy.wait('@retryUploadRequest');

        // Verify success message
        cy.get('.upload-status').should('contain', 'Upload successful');
    });

    it('should show an error message if retry fails', () => {
        const filePath = 'path/to/your/file.txt'; // Replace with the actual file path

        // Simulate a failed upload
        cy.get('input[type="file"]').attachFile(filePath);
        cy.get('button.upload').click();
        cy.intercept('POST', '/upload', { statusCode: 500 }).as('uploadRequest'); // Simulate server error
        cy.wait('@uploadRequest');

        // Retry the upload
        cy.get('button.retry').click();
        cy.intercept('POST', '/upload', { statusCode: 500 }).as('retryUploadRequest'); // Simulate retry failure
        cy.wait('@retryUploadRequest');

        // Verify error message
        cy.get('.upload-status').should('contain', 'Upload failed, please try again');
    });
});
